steps.body:
A conditional type is a ternary for types. `T extends U ? X : Y` checks whether `T` fits `U`, the same question an assignment asks, and becomes `X` if it does, else `Y`. Chain them like ternaries to test several cases in order:

```typescript types
type IsText<T> = T extends string ? "text" : "not text";

type A = IsText<"hello">;
//   ^? type A = "text"
type B = IsText<42>;
//   ^? type B = "not text"
```

Conditions earn their keep in generic types, where `T` is whatever the caller passes. TypeScript's own library has several. `Exclude<T, U>`, for example, is declared as `T extends U ? never : T`, and `Extract<T, U>` as `T extends U ? T : never`.

A condition exists only for `tsc`. It picks a type, and nothing of it runs. To check a value while the program runs, you still use `typeof`, `in`, and type guards.

examples.code:
type TypeName<T> = T extends string ? "string" : T extends number ? "number" : "other";

type A = TypeName<"Ada">;
//   ^? type A = "string"
type B = TypeName<36>;
//   ^? type B = "number"
type C = TypeName<string[]>;
//   ^? type C = "other"

function describe<T>(value: T, name: TypeName<T>): string {
  return `${JSON.stringify(value)}: ${name}`;
}

console.log(describe("Ada", "string"));
console.log(describe(36, "number"));
console.log(describe(["a", "b"], "other"));

examples.explanation:
The conditions run in order, like an `if` followed by `else if`. `string[]` is neither a string nor a number, so it gets `"other"`. In `describe`, `T` comes from `value`, and the type of `name` is computed from it, so the name has to match the value:

```typescript error
type TypeName<T> = T extends string ? "string" : T extends number ? "number" : "other";

function describe<T>(value: T, name: TypeName<T>): string {
  return `${JSON.stringify(value)}: ${name}`;
}

describe(36, "string");
```

For `36`, `name` must be `"number"`, so `tsc` reports TS2345: `Argument of type '"string"' is not assignable to parameter of type '"number"'.`

examples.code:
type MyNonNullable<T> = T extends null | undefined ? never : T;

type MaybeName = string | null | undefined;

type Name = MyNonNullable<MaybeName>;
//   ^? type Name = string
type Same = NonNullable<MaybeName>;
//   ^? type Same = string

function greet(name: Name): string {
  return `Hello, ${name}!`;
}

const names: MaybeName[] = ["Ada", null, "Grace", undefined];
for (const n of names) {
  console.log(n === null || n === undefined ? "Hello, guest!" : greet(n));
}

type ElementOrSelf<T> = T extends readonly unknown[] ? T[number] : T;

type Config = {
  hosts: string[];
  port: number;
  sizes: readonly ["S", "M", "L"];
};

type Host = ElementOrSelf<Config["hosts"]>;
//   ^? type Host = string
type Port = ElementOrSelf<Config["port"]>;
//   ^? type Port = number
type Size = ElementOrSelf<Config["sizes"]>;
//   ^? type Size = "L" | "M" | "S"

function url(host: Host, port: Port): string {
  return `https://${host}:${port}`;
}

const config: Config = { hosts: ["api.example.com", "backup.example.com"], port: 8443, sizes: ["S", "M", "L"] };
const defaultSize: Size = "M";

for (const host of config.hosts) {
  console.log(url(host, config.port));
}
console.log(`Default size: ${defaultSize}`);

