practice.solution:
export type AppEvent =
  | { type: "login"; userId: string }
  | { type: "logout"; userId: string }
  | { type: "tick"; at: number };

export type HasField<T, K extends string> = T extends Record<K, unknown> ? T : never;

export type WithUser = HasField<AppEvent, "userId">;

export function hasUser(e: AppEvent): e is WithUser {
  return "userId" in e;
}

const events: AppEvent[] = [
  { type: "login", userId: "u1" },
  { type: "tick", at: 1 },
  { type: "login", userId: "u2" },
  { type: "logout", userId: "u1" },
  { type: "tick", at: 2 },
  { type: "login", userId: "u3" },
  { type: "logout", userId: "u2" },
];

const withUser = events.filter(hasUser);
console.log(`${withUser.length} of ${events.length} events have a user`);

const users = new Set(withUser.map((e) => e.userId));
console.log(`Users: ${[...users].join(", ")}`);

