practice.solution:
export const handlers = {
  greet: (p: { name: string }) => `Hello, ${p.name}!`,
  add: (p: { a: number; b: number }) => `${p.a} + ${p.b} = ${p.a + p.b}`,
};

export type PayloadOf<F> = F extends (payload: infer P) => void ? P : never;

const greetings: PayloadOf<typeof handlers.greet>[] = [{ name: "Ada" }, { name: "Grace" }];
const sums: PayloadOf<typeof handlers.add>[] = [
  { a: 2, b: 3 },
  { a: 10, b: -4 },
];

for (const p of greetings) {
  console.log(handlers.greet(p));
}
for (const p of sums) {
  console.log(handlers.add(p));
}
